const facilityName = (facilityId:string) => facilities.find(f=>f.id===facilityId)?.name ?? facilityId;
const availableBeds = (facilityId:string, bedType:BedType) => { const c=bedCapacity.find(x=>x.facilityId===facilityId&&x.bedType===bedType); return c ? Math.max(0,c.staffedBeds-c.occupiedBeds-c.reservedBeds) : 0; };
const facilityCapacity = (facilityId:string) => bedCapacity.filter(c=>c.facilityId===facilityId).map(c=>({...c,availableBeds:Math.max(0,c.staffedBeds-c.occupiedBeds-c.reservedBeds)}));
const bedTypeForService = (service:string):BedType|undefined => /surgery|oncology|admission|inpatient/i.test(service) ? 'GENERAL' : undefined;
