function ensureExpandedPatients(target=120){
  if(patients.length>=target)return;
  const originals=[...patients];
  const firstNames=['Amahle','Katlego','Lethabo','Zinhle','Lwazi','Tebogo','Anele','Siyabonga','Rethabile','Nthabiseng','Khumo','Lukhanyo','Mpumelelo','Nompumelelo','Onalenna','Tshegofatso','Zola','Minenhle','Keitumetse','Asanda'];
  const surnames=['Mokoena','Nkosi','Molefe','Dlamini','Mabena','Mahlangu','Sithole','Ndlovu','Radebe','Maseko','Motaung','Khumalo','Mofokeng','Modise','Baloyi','Mthembu','Shabangu','Mhlongo','Nkomo','Mabaso'];
  for(let i=patients.length;i<target;i++){
    const base=originals[i%originals.length];
    const n=i+1;
    const suffix=`${n}`;
    patients.push({
      ...base,
      id:`pat-${String(n).padStart(3,'0')}`,
      syntheticId:`SYN-CP-${String(n).padStart(4,'0')}`,
      firstName:firstNames[i%firstNames.length],
      surname:surnames[(i*3)%surnames.length],
      dateOfBirth:`${1958+(i%48)}-${String((i%12)+1).padStart(2,'0')}-${String((i%27)+1).padStart(2,'0')}`,
      phone:`+27 71 500 ${String(n).padStart(4,'0')}`,
      allergies:base.allergies.map((x,j)=>({...x,id:`all-${suffix}-${j+1}`})),
      conditions:base.conditions.map((x,j)=>({...x,id:`cond-${suffix}-${j+1}`})),
      medications:base.medications.map((x,j)=>({...x,id:`med-${suffix}-${j+1}`})),
      results:base.results.map((x,j)=>({...x,id:`res-${suffix}-${j+1}`})),
      encounters:base.encounters.map((x,j)=>({...x,id:`enc-${suffix}-${j+1}`}))
    });
  }
}
ensureExpandedPatients(120);

type NotificationKind='APPOINTMENT'|'REFERRAL'|'CAPACITY'|'MEDICATION'|'VACCINE'|'TRANSFER'|'SYSTEM';
type NotificationPriority='LOW'|'MEDIUM'|'HIGH';
interface CareNotification{ id:string; kind:NotificationKind; priority:NotificationPriority; title:string; message:string; createdAt:string; patientId?:string; facilityId?:string; recipientUserId?:string; roles?:Role[]; actionView?:string; readBy:string[]; }
interface VaccineRecord{ id:string; patientId:string; vaccine:string; dose:string; administeredAt:string; administeredFacility:string; nextDueAt?:string; status:'COMPLETE'|'DUE'|'OVERDUE'; synthetic:true; }
type AmbulanceType='BASIC'|'ADVANCED'|'ICU'|'NEONATAL';
type AmbulanceStatus='AVAILABLE'|'DISPATCHED'|'MAINTENANCE';
interface Ambulance{ id:string; callSign:string; type:AmbulanceType; status:AmbulanceStatus; stationFacilityId:string; crew:string; capabilities:string[]; etaMinutes:number; updatedAt:string; synthetic:true; }
type TransferPriority='ROUTINE'|'URGENT'|'EMERGENCY';
type TransferStatus='REQUESTED'|'ASSIGNED'|'EN_ROUTE'|'PATIENT_ON_BOARD'|'ARRIVED'|'COMPLETED'|'CANCELLED';
interface TransferRequest{ id:string; patientId:string; referralId?:string; pickupFacilityId:string; destinationFacilityId:string; ambulanceId?:string; priority:TransferPriority; requiredLevel:AmbulanceType; scheduledAt:string; status:TransferStatus; requestedBy:string; note?:string; createdAt:string; updatedAt:string; synthetic:true; }

const vaccinations:VaccineRecord[]=[];
const vaccineNames=['Influenza','COVID-19 booster','Tetanus','Hepatitis B','Pneumococcal'];
for(let i=0;i<patients.length;i++){
  if(i%2!==0)continue;
  const p=patients[i];
  const daysOffset=(i%5===0?-20:i%5===1?14:120);
  const next=new Date(Date.now()+daysOffset*86400000);
  vaccinations.push({id:`vax-${i+1}-1`,patientId:p.id,vaccine:vaccineNames[i%vaccineNames.length],dose:i%3===0?'Booster':'Dose 1',administeredAt:new Date(Date.now()-(120+i%180)*86400000).toISOString(),administeredFacility:i%2===0?'Mahlasedi Community Clinic (Demo)':'Ubuntu Community Health Centre (Demo)',nextDueAt:next.toISOString(),status:daysOffset<0?'OVERDUE':daysOffset<=30?'DUE':'COMPLETE',synthetic:true});
}

