const notifications:CareNotification[]=[];
function addNotification(input:Omit<CareNotification,'id'|'createdAt'|'readBy'>){notifications.unshift({id:randomUUID(),createdAt:nowIso(),readBy:[],...input})}
function seedNotifications(){
  if(notifications.length)return;
  appointments.slice(0,8).forEach((a,i)=>addNotification({kind:'APPOINTMENT',priority:i%3===0?'HIGH':'MEDIUM',title:'Appointment reminder',message:`${patientName(a.patientId)} has a ${a.service} appointment at ${facilityName(a.facilityId)}.`,patientId:a.patientId,facilityId:a.facilityId,actionView:'appointments'}));
  referrals.filter(r=>['SUBMITTED','RECEIVED','INFO_REQUESTED'].includes(r.status)).slice(0,6).forEach(r=>addNotification({kind:'REFERRAL',priority:'HIGH',title:'Referral requires attention',message:`${patientName(r.patientId)} — ${r.service} referral is ${r.status.toLowerCase().replace('_',' ')}.`,patientId:r.patientId,facilityId:r.destinationFacilityId,roles:['COORDINATOR','SPECIALIST','MANAGER','ADMIN'],actionView:'referrals'}));
  vaccinations.filter(v=>v.status!=='COMPLETE').slice(0,8).forEach(v=>addNotification({kind:'VACCINE',priority:v.status==='OVERDUE'?'HIGH':'MEDIUM',title:v.status==='OVERDUE'?'Vaccination overdue':'Vaccination due soon',message:`${patientName(v.patientId)} — ${v.vaccine} ${v.dose}.`,patientId:v.patientId,roles:['CLINICIAN','NURSE','PHARMACIST','PATIENT_NAVIGATOR'],actionView:'medication'}));
  bedCapacity.filter(c=>availableBeds(c.facilityId,c.bedType)<=1).slice(0,5).forEach(c=>addNotification({kind:'CAPACITY',priority:'HIGH',title:'Bed capacity constrained',message:`${facilityName(c.facilityId)} has ${availableBeds(c.facilityId,c.bedType)} ${c.bedType.toLowerCase().replace('_',' ')} beds available in the synthetic feed.`,facilityId:c.facilityId,roles:['COORDINATOR','MANAGER','ADMIN','NURSE'],actionView:'facilities'}));
  transfers.forEach(t=>addNotification({kind:'TRANSFER',priority:t.priority==='EMERGENCY'?'HIGH':'MEDIUM',title:'Patient transfer update',message:`${patientName(t.patientId)} transfer is ${t.status.toLowerCase().replaceAll('_',' ')}.`,patientId:t.patientId,facilityId:t.destinationFacilityId,roles:['COORDINATOR','NURSE','PATIENT_NAVIGATOR','MANAGER'],actionView:'transfers'}));
}
seedNotifications();

function visibleReferralsFor(user: typeof users[number]) {
  if (managementRoles.includes(user.role)) return referrals;
  if (user.role === 'PATIENT') return referrals.filter(r=>r.patientId===user.patientId);
  if (!user.facilityId) return [];
  return referrals.filter(r=>r.sourceFacilityId===user.facilityId||r.destinationFacilityId===user.facilityId);
}

function visiblePatientIdsFor(user: typeof users[number]):Set<string> {
  if (managementRoles.includes(user.role)) return new Set(patients.map(p=>p.id));
  if (user.role === 'PATIENT') return new Set(user.patientId?[user.patientId]:[]);
  const ids=new Set(visibleReferralsFor(user).map(r=>r.patientId));
  const ownFacility=user.facilityId?facilityName(user.facilityId):'';
  if(ownFacility){for(const p of patients){const items=[...p.allergies,...p.conditions,...p.medications,...p.results,...p.encounters];if(items.some(i=>i.sourceFacility===ownFacility))ids.add(p.id)}}
  return ids;
}
function canReadPatient(user: typeof users[number], patientId:string){return Boolean(patientId)&&visiblePatientIdsFor(user).has(patientId)}
function visibleAppointmentsFor(user: typeof users[number]) {
  if (managementRoles.includes(user.role)) return appointments;
  if (user.role==='PATIENT') return appointments.filter(a=>a.patientId===user.patientId);
  const referralIds=new Set(visibleReferralsFor(user).map(r=>r.id));
  return appointments.filter(a=>a.facilityId===user.facilityId||(a.referralId&&referralIds.has(a.referralId)));
}
function visibleTransfersFor(user: typeof users[number]){
  if(managementRoles.includes(user.role))return transfers;
  if(user.role==='PATIENT')return transfers.filter(t=>t.patientId===user.patientId);
  if(!user.facilityId)return [];
  return transfers.filter(t=>t.pickupFacilityId===user.facilityId||t.destinationFacilityId===user.facilityId||canReadPatient(user,t.patientId));
}
function visibleNotificationsFor(user: typeof users[number]){
  if(managementRoles.includes(user.role))return notifications;
  return notifications.filter(n=>n.recipientUserId===user.id||(user.role==='PATIENT'&&n.patientId===user.patientId)||(Boolean(user.facilityId)&&n.facilityId===user.facilityId)||(n.roles?.includes(user.role)));
}

function roleCanTransition(role:Role,to:ReferralStatus){
  if(role==='ADMIN')return true;
  if(role==='CLINICIAN')return ['SUBMITTED','CANCELLED'].includes(to);
  if(role==='COORDINATOR'||role==='SPECIALIST')return ['RECEIVED','INFO_REQUESTED','ACCEPTED','DECLINED','REDIRECTED','SCHEDULED','PATIENT_NOTIFIED','ATTENDED','MISSED','FEEDBACK_PENDING','FOLLOWUP_REQUIRED','CLOSED'].includes(to);
  if(role==='NURSE')return ['PATIENT_NOTIFIED','ATTENDED','MISSED','FOLLOWUP_REQUIRED'].includes(to);
  if(role==='PATIENT_NAVIGATOR')return ['PATIENT_NOTIFIED','FOLLOWUP_REQUIRED','SCHEDULED'].includes(to);
  if(role==='MANAGER')return ['REOPENED'].includes(to);
  return false;
}

function logAudit(actor:string,action:string,objectType:string,objectId:string,source:'UI'|'VOICE'|'AI'|'SYSTEM',outcome:'SUCCESS'|'DENIED'='SUCCESS',reason?:string){auditEvents.unshift({id:randomUUID(),at:nowIso(),actor,action,objectType,objectId,source,outcome,reason})}
function referralView(r:Referral){return {...r,patientName:patientName(r.patientId),sourceFacilityName:facilityName(r.sourceFacilityId),destinationFacilityName:facilityName(r.destinationFacilityId),bedAvailability:r.requiresBed&&r.bedType?{bedType:r.bedType,available:availableBeds(r.destinationFacilityId,r.bedType)}:null}}
function appointmentView(a:Appointment){return {...a,patientName:patientName(a.patientId),facilityName:facilityName(a.facilityId),referral:a.referralId?referrals.find(r=>r.id===a.referralId):undefined,bedAvailability:a.requiresBed&&a.bedType?availableBeds(a.facilityId,a.bedType):null}}
function transferView(t:TransferRequest){const ambulance=t.ambulanceId?ambulances.find(a=>a.id===t.ambulanceId):undefined;return {...t,patientName:patientName(t.patientId),pickupFacilityName:facilityName(t.pickupFacilityId),destinationFacilityName:facilityName(t.destinationFacilityId),ambulance:ambulance?{...ambulance,stationName:facilityName(ambulance.stationFacilityId)}:null}}
function ambulanceView(a:Ambulance){const activeTransfer=transfers.find(t=>t.ambulanceId===a.id&&!['COMPLETED','CANCELLED'].includes(t.status));return {...a,stationName:facilityName(a.stationFacilityId),activeTransfer:activeTransfer?{id:activeTransfer.id,patientName:patientName(activeTransfer.patientId),status:activeTransfer.status,destinationFacilityName:facilityName(activeTransfer.destinationFacilityId)}:null}}
function alternativesFor(service:string,bedType:BedType){return facilities.filter(f=>(f.type==='PUBLIC'||f.type==='PRIVATE')&&f.services.some(s=>s.toLowerCase().includes(service.toLowerCase().split(' ')[0]))&&availableBeds(f.id,bedType)>0).map(f=>({facilityId:f.id,facilityName:f.name,availableBeds:availableBeds(f.id,bedType),bedType}))}
function reserveBed(facilityId:string,bedType:BedType){const c=bedCapacity.find(x=>x.facilityId===facilityId&&x.bedType===bedType);if(!c||availableBeds(facilityId,bedType)<1)return false;c.reservedBeds+=1;c.updatedAt=nowIso();return true}
function releaseReservedBed(facilityId:string,bedType?:BedType){if(!bedType)return;const c=bedCapacity.find(x=>x.facilityId===facilityId&&x.bedType===bedType);if(c&&c.reservedBeds>0){c.reservedBeds-=1;c.updatedAt=nowIso()}}
function checkInBed(facilityId:string,bedType?:BedType){if(!bedType)return;const c=bedCapacity.find(x=>x.facilityId===facilityId&&x.bedType===bedType);if(c){if(c.reservedBeds>0)c.reservedBeds-=1;c.occupiedBeds=Math.min(c.staffedBeds,c.occupiedBeds+1);c.updatedAt=nowIso()}}
function dischargeBed(facilityId:string,bedType?:BedType){if(!bedType)return;const c=bedCapacity.find(x=>x.facilityId===facilityId&&x.bedType===bedType);if(c&&c.occupiedBeds>0){c.occupiedBeds-=1;c.updatedAt=nowIso()}}

function ambulanceCanServe(a:Ambulance,required:AmbulanceType){if(a.status!=='AVAILABLE')return false;if(required==='BASIC')return true;if(required==='ADVANCED')return ['ADVANCED','ICU','NEONATAL'].includes(a.type);if(required==='ICU')return a.type==='ICU';return a.type==='NEONATAL'}
function findAmbulance(required:AmbulanceType){return ambulances.filter(a=>ambulanceCanServe(a,required)).sort((a,b)=>a.etaMinutes-b.etaMinutes)[0]}
function assignAmbulance(transfer:TransferRequest,ambulance:Ambulance){transfer.ambulanceId=ambulance.id;transfer.status='ASSIGNED';transfer.updatedAt=nowIso();ambulance.status='DISPATCHED';ambulance.updatedAt=transfer.updatedAt}
function releaseAmbulance(ambulanceId?:string){if(!ambulanceId)return;const ambulance=ambulances.find(a=>a.id===ambulanceId);if(ambulance&&ambulance.status==='DISPATCHED'){ambulance.status='AVAILABLE';ambulance.updatedAt=nowIso()}}

function outcomeSummary(source:Referral[]){const hospitalFacilities=facilities.filter(f=>f.type==='PUBLIC'||f.type==='PRIVATE');return hospitalFacilities.map(f=>{const referred=source.filter(r=>r.destinationFacilityId===f.id);const withOutcome=referred.filter(r=>r.outcome&&r.outcome!=='UNKNOWN');const count=(outcome:CareOutcome)=>withOutcome.filter(r=>r.outcome===outcome).length;const recovered=count('RECOVERED'),improved=count('IMPROVED'),deceased=count('DECEASED'),ongoing=count('ONGOING'),favourable=recovered+improved,resolved=favourable+deceased;const acknowledged=referred.filter(r=>r.acknowledgedAt);const medianAckHours=acknowledged.length?Math.round(acknowledged.map(r=>Math.max(0,(Date.parse(r.acknowledgedAt!)-Date.parse(r.createdAt))/3600000)).sort((a,b)=>a-b)[Math.floor(acknowledged.length/2)]*10)/10:null;return{facilityId:f.id,facilityName:f.name,type:f.type,province:f.province,referred:referred.length,outcomesRecorded:withOutcome.length,recovered,improved,deceased,ongoing,unknown:referred.length-withOutcome.length,favourableObservedPct:resolved?Math.round(favourable/resolved*100):null,medianAckHours}}).filter(x=>x.referred>0).sort((a,b)=>(b.favourableObservedPct??-1)-(a.favourableObservedPct??-1))}

function accessProfile(role:Role){const matrix:Record<Role,string[]>={ADMIN:['All synthetic records','User/role administration','OpenAI API settings','Appointment Management Centre','Notifications','Medication & Vaccine Management','Ambulance and transfer management','Bed capacity','Audit','All referral actions','Outcome analytics'],CLINICIAN:['Scoped patient records','Create/submit referrals','Book appointments','Medication management','Vaccination management','Request patient transfer','Check destination capacity','Ayanda governed actions','Care gaps','Notifications'],SPECIALIST:['Receiving-facility patients','Accept/coordinate referrals','Appointment management','Medication management','Vaccination management','Request patient transfer','Record outcomes','Bed capacity','Care gaps'],NURSE:['Receiving-facility patient context','Check-in/follow-up updates','Vaccination management','Ambulance transfer workflow','Bed capacity','Patient navigation','Notifications'],COORDINATOR:['Receiving/referring queues','Appointment scheduling','Ambulance dispatch','Bed-capacity checks','Referral transitions','Record outcomes','Notifications'],PHARMACIST:['Scoped medication context','Medication reconciliation','Vaccination records','Patient record provenance','Notifications'],LAB_TECH:['Scoped result context','Diagnostic-result provenance'],PATIENT_NAVIGATOR:['Scoped referrals','Appointment booking','Transfer requests','Follow-up','Patient communication workflow','Notifications'],MANAGER:['All synthetic operational data','Capacity analytics','Ambulance availability','Transfer analytics','Outcome analytics','Command Centre','Audit','Notifications'],AUDITOR:['Read-only records','Audit/provenance','Access-event review','Read-only transfer and notification context'],PATIENT:['Own synthetic OneRecord','Own referrals','Own appointments','Own medications/vaccines','Own transfer status','Own notifications','Own Health Passport']};return matrix[role]}

app.get('/api/health',(_req,res)=>res.json({ok:true,service:'carepath-api',version:'0.4.0',syntheticData:true,patients:patients.length}));
app.post('/api/auth/login',async(req,res)=>{const username=String(req.body?.username||'').trim().toLowerCase(),password=String(req.body?.password||'');const user=users.find(u=>u.username===username);if(!user||!(await bcrypt.compare(password,user.passwordHash)))return res.status(401).json({error:'Invalid demo credentials'});req.session.userId=user.id;logAudit(user.displayName,'auth.login','User',user.id,'UI');res.json({user:safeUser(user),syntheticData:true})});
