app.post('/api/appointments',auth,requireRole(...bookingRoles),(req,res)=>{const patientId=String(req.body?.patientId||''),facilityId=String(req.body?.facilityId||''),service=String(req.body?.service||'').trim(),startAt=String(req.body?.startAt||''),referralId=req.body?.referralId?String(req.body.referralId):undefined,durationMinutes=Math.min(240,Math.max(15,Number(req.body?.durationMinutes||30)));if(!patientId||!facilityId||!service||!startAt)return res.status(400).json({error:'Patient, facility, service and appointment time are required'});if(!canReadPatient(req.currentUser!,patientId))return res.status(403).json({error:'Patient is outside authorised scope'});if(!facilities.some(f=>f.id===facilityId))return res.status(400).json({error:'Invalid facility'});if(!Number.isFinite(Date.parse(startAt))||Date.parse(startAt)<Date.now()-5*60*1000)return res.status(400).json({error:'Appointment must have a valid current or future time'});const referral=referralId?referrals.find(r=>r.id===referralId):undefined;if(referralId&&!referral)return res.status(404).json({error:'Referral not found'});const bedType:BedType|undefined=referral?.bedType||(req.body?.requiresBed===true?String(req.body?.bedType||'GENERAL') as BedType:bedTypeForService(service));if(bedType&&!reserveBed(facilityId,bedType))return res.status(409).json({error:`No synthetic ${bedType.toLowerCase().replace('_',' ')} bed is available at ${facilityName(facilityId)} for this booking`,alternatives:alternativesFor(service,bedType)});const appt:Appointment={id:`appt-${Date.now()}`,patientId,facilityId,referralId,service,startAt:new Date(startAt).toISOString(),durationMinutes,status:'BOOKED',bookedBy:req.currentUser!.displayName,bookingSource:'UI',requiresBed:Boolean(bedType),bedType,note:String(req.body?.note||'').slice(0,400)||undefined,createdAt:nowIso(),updatedAt:nowIso()};appointments.push(appt);if(referral){referral.appointmentAt=appt.startAt;if(referral.status==='ACCEPTED')referral.status='SCHEDULED';referral.updatedAt=appt.updatedAt;referral.events.unshift({id:randomUUID(),at:appt.updatedAt,actor:req.currentUser!.displayName,from:'ACCEPTED',to:referral.status,note:`Appointment booked for ${appt.startAt}`,source:'UI'})}addNotification({kind:'APPOINTMENT',priority:'MEDIUM',title:'Appointment booked',message:`${patientName(patientId)} — ${service} at ${facilityName(facilityId)} on ${new Date(appt.startAt).toLocaleString('en-ZA')}.`,patientId,facilityId,actionView:'appointments'});logAudit(req.currentUser!.displayName,'appointment.book','Appointment',appt.id,'UI');res.status(201).json({appointment:appointmentView(appt)})});
app.post('/api/referrals/:id/book',auth,requireRole(...bookingRoles),(req,res)=>{const referralId=paramValue(req.params.id),referral=referrals.find(r=>r.id===referralId);if(!referral||!visibleReferralsFor(req.currentUser!).some(r=>r.id===referral.id))return res.status(404).json({error:'Referral not found in authorised scope'});if(!['ACCEPTED','SCHEDULED','PATIENT_NOTIFIED'].includes(referral.status))return res.status(409).json({error:'Referral must be accepted before an appointment can be booked'});const existing=appointments.find(a=>a.referralId===referral.id&&!['CANCELLED','NO_SHOW'].includes(a.status));if(existing)return res.status(409).json({error:'An active appointment already exists for this referral',appointment:appointmentView(existing)});const startAt=String(req.body?.startAt||'');if(!Number.isFinite(Date.parse(startAt))||Date.parse(startAt)<Date.now())return res.status(400).json({error:'A valid future appointment time is required'});if(referral.requiresBed&&referral.bedType&&!reserveBed(referral.destinationFacilityId,referral.bedType))return res.status(409).json({error:`No synthetic ${referral.bedType.toLowerCase().replace('_',' ')} bed is available at ${facilityName(referral.destinationFacilityId)}`,alternatives:alternativesFor(referral.service,referral.bedType)});const appt:Appointment={id:`appt-${Date.now()}`,patientId:referral.patientId,facilityId:referral.destinationFacilityId,referralId:referral.id,service:referral.service,startAt:new Date(startAt).toISOString(),durationMinutes:Math.min(240,Math.max(15,Number(req.body?.durationMinutes||30))),status:'BOOKED',bookedBy:req.currentUser!.displayName,bookingSource:'UI',requiresBed:Boolean(referral.requiresBed),bedType:referral.bedType,note:'Booked from accepted referral',createdAt:nowIso(),updatedAt:nowIso()};appointments.push(appt);referral.appointmentAt=appt.startAt;referral.status='SCHEDULED';referral.updatedAt=appt.updatedAt;referral.events.unshift({id:randomUUID(),at:appt.updatedAt,actor:req.currentUser!.displayName,from:'ACCEPTED',to:'SCHEDULED',note:`Appointment booked for ${appt.startAt}`,source:'UI'});addNotification({kind:'APPOINTMENT',priority:'MEDIUM',title:'Referral appointment booked',message:`${patientName(referral.patientId)} — ${referral.service} booked at ${facilityName(referral.destinationFacilityId)}.`,patientId:referral.patientId,facilityId:referral.destinationFacilityId,actionView:'appointments'});logAudit(req.currentUser!.displayName,'referral.appointment.book','Referral',referral.id,'UI');res.status(201).json({appointment:appointmentView(appt),referral:referralView(referral)})});
