app.post('/api/appointments/:id/status',auth,(req,res)=>{const appointmentId=paramValue(req.params.id),appt=appointments.find(a=>a.id===appointmentId);if(!appt||!visibleAppointmentsFor(req.currentUser!).some(a=>a.id===appt.id))return res.status(404).json({error:'Appointment not found in authorised scope'});const to=String(req.body?.status||'') as AppointmentStatus;if(!appointmentTransitions[appt.status]?.includes(to))return res.status(409).json({error:`Invalid appointment transition from ${appt.status} to ${to}`});const role=req.currentUser!.role;if(role==='PATIENT'&&to!=='CANCELLED')return res.status(403).json({error:'Patient role may cancel but not clinically progress an appointment'});if(!['ADMIN','SPECIALIST','NURSE','COORDINATOR','PATIENT_NAVIGATOR','CLINICIAN','PATIENT'].includes(role))return res.status(403).json({error:'Role is not authorised to manage appointments'});const from=appt.status;if(to==='CANCELLED'&&appt.requiresBed)releaseReservedBed(appt.facilityId,appt.bedType);if(to==='CHECKED_IN'&&appt.requiresBed)checkInBed(appt.facilityId,appt.bedType);if(to==='COMPLETED'&&appt.requiresBed)dischargeBed(appt.facilityId,appt.bedType);appt.status=to;appt.updatedAt=nowIso();addNotification({kind:'APPOINTMENT',priority:to==='NO_SHOW'?'HIGH':'MEDIUM',title:`Appointment ${to.toLowerCase().replace('_',' ')}`,message:`${patientName(appt.patientId)} — ${appt.service} appointment status changed to ${to.toLowerCase().replace('_',' ')}.`,patientId:appt.patientId,facilityId:appt.facilityId,actionView:'appointments'});logAudit(req.currentUser!.displayName,`appointment.${to.toLowerCase()}`,'Appointment',appt.id,'UI','SUCCESS',`${from} -> ${to}`);res.json({appointment:appointmentView(appt)})});

