app.post('/api/patients/:id/medications',auth,requireRole(...medicationWriteRoles),(req,res)=>{const patientId=paramValue(req.params.id),patient=patients.find(p=>p.id===patientId);if(!patient||!canReadPatient(req.currentUser!,patientId))return res.status(404).json({error:'Patient not found in authorised scope'});const label=String(req.body?.label||'').trim(),detail=String(req.body?.detail||'').trim();if(!label)return res.status(400).json({error:'Medication name and dose are required'});const item={id:`med-${Date.now()}`,label:label.slice(0,160),detail:detail.slice(0,300)||'Synthetic medication management entry',recordedAt:nowIso(),sourceFacility:req.currentUser!.facilityId?facilityName(req.currentUser!.facilityId):'CarePath Administration (Demo)',status:'Current'};patient.medications.unshift(item);addNotification({kind:'MEDICATION',priority:'MEDIUM',title:'Medication record updated',message:`${patientName(patientId)} — ${item.label} added to the synthetic longitudinal record.`,patientId,facilityId:req.currentUser!.facilityId||undefined,roles:['PHARMACIST','CLINICIAN'],actionView:'medication'});logAudit(req.currentUser!.displayName,'medication.add','Patient',patientId,'UI');res.status(201).json({medication:item})});
app.post('/api/patients/:id/medications/:medId/status',auth,requireRole(...medicationWriteRoles),(req,res)=>{const patientId=paramValue(req.params.id),medId=paramValue(req.params.medId),patient=patients.find(p=>p.id===patientId);if(!patient||!canReadPatient(req.currentUser!,patientId))return res.status(404).json({error:'Patient not found in authorised scope'});const med=patient.medications.find(m=>m.id===medId);if(!med)return res.status(404).json({error:'Medication not found'});const status=String(req.body?.status||'');if(!['Current','Stopped','On hold'].includes(status))return res.status(400).json({error:'Invalid medication status'});med.status=status;logAudit(req.currentUser!.displayName,'medication.status.update','Medication',med.id,'UI');res.json({medication:med})});
app.post('/api/patients/:id/vaccinations',auth,requireRole(...vaccineWriteRoles),(req,res)=>{const patientId=paramValue(req.params.id),patient=patients.find(p=>p.id===patientId);if(!patient||!canReadPatient(req.currentUser!,patientId))return res.status(404).json({error:'Patient not found in authorised scope'});const vaccine=String(req.body?.vaccine||'').trim(),dose=String(req.body?.dose||'').trim(),nextDueAt=req.body?.nextDueAt?String(req.body.nextDueAt):undefined;if(!vaccine||!dose)return res.status(400).json({error:'Vaccine and dose are required'});const nextMs=nextDueAt?Date.parse(nextDueAt):NaN,status:VaccineRecord['status']=Number.isFinite(nextMs)?(nextMs<Date.now()?'OVERDUE':nextMs<=Date.now()+30*86400000?'DUE':'COMPLETE'):'COMPLETE';const record:VaccineRecord={id:`vax-${Date.now()}`,patientId,vaccine:vaccine.slice(0,140),dose:dose.slice(0,80),administeredAt:nowIso(),administeredFacility:req.currentUser!.facilityId?facilityName(req.currentUser!.facilityId):'CarePath Administration (Demo)',nextDueAt:Number.isFinite(nextMs)?new Date(nextMs).toISOString():undefined,status,synthetic:true};vaccinations.unshift(record);addNotification({kind:'VACCINE',priority:status==='OVERDUE'?'HIGH':'MEDIUM',title:'Vaccination record updated',message:`${patientName(patientId)} — ${record.vaccine} ${record.dose} recorded.`,patientId,facilityId:req.currentUser!.facilityId||undefined,roles:['CLINICIAN','NURSE','PHARMACIST'],actionView:'medication'});logAudit(req.currentUser!.displayName,'vaccination.add','Patient',patientId,'UI');res.status(201).json({vaccination:record})});

app.get('/api/ambulances',auth,(req,res)=>{const visible=req.currentUser!.role==='PATIENT'?ambulances.filter(a=>visibleTransfersFor(req.currentUser!).some(t=>t.ambulanceId===a.id)):ambulances;res.json({syntheticData:true,disclaimer:'Synthetic ambulance availability and ETA data for hackathon demonstration only; not a live EMS dispatch feed.',ambulances:visible.map(ambulanceView),summary:{available:ambulances.filter(a=>a.status==='AVAILABLE').length,dispatched:ambulances.filter(a=>a.status==='DISPATCHED').length,maintenance:ambulances.filter(a=>a.status==='MAINTENANCE').length,total:ambulances.length}})});
app.get('/api/transfers',auth,(req,res)=>res.json({syntheticData:true,transfers:visibleTransfersFor(req.currentUser!).sort((a,b)=>Date.parse(b.updatedAt)-Date.parse(a.updatedAt)).map(transferView)}));
app.post('/api/transfers',auth,requireRole(...transferWriteRoles),(req,res)=>{const patientId=String(req.body?.patientId||''),referralId=req.body?.referralId?String(req.body.referralId):undefined,pickupFacilityId=String(req.body?.pickupFacilityId||''),destinationFacilityId=String(req.body?.destinationFacilityId||''),priority=String(req.body?.priority||'ROUTINE') as TransferPriority,requiredLevel=String(req.body?.requiredLevel||'BASIC') as AmbulanceType,scheduledAt=String(req.body?.scheduledAt||nowIso());if(!canReadPatient(req.currentUser!,patientId))return res.status(403).json({error:'Patient is outside authorised scope'});if(!facilities.some(f=>f.id===pickupFacilityId)||!facilities.some(f=>f.id===destinationFacilityId))return res.status(400).json({error:'Valid pickup and destination facilities are required'});if(!['ROUTINE','URGENT','EMERGENCY'].includes(priority))return res.status(400).json({error:'Invalid transfer priority'});if(!['BASIC','ADVANCED','ICU','NEONATAL'].includes(requiredLevel))return res.status(400).json({error:'Invalid ambulance level'});const referral=referralId?referrals.find(r=>r.id===referralId):undefined;if(referralId&&!referral)return res.status(404).json({error:'Referral not found'});if(referral?.requiresBed&&referral.bedType&&availableBeds(destinationFacilityId,referral.bedType)<1)return res.status(409).json({error:`Patient transfer blocked: no synthetic ${referral.bedType.toLowerCase().replace('_',' ')} bed is available at ${facilityName(destinationFacilityId)}`,alternatives:alternativesFor(referral.service,referral.bedType)});const transfer:TransferRequest={id:`trn-${Date.now()}`,patientId,referralId,pickupFacilityId,destinationFacilityId,priority,requiredLevel,scheduledAt:Number.isFinite(Date.parse(scheduledAt))?new Date(scheduledAt).toISOString():nowIso(),status:'REQUESTED',requestedBy:req.currentUser!.displayName,note:String(req.body?.note||'').slice(0,400)||undefined,createdAt:nowIso(),updatedAt:nowIso(),synthetic:true};const ambulance=findAmbulance(requiredLevel);if(ambulance)assignAmbulance(transfer,ambulance);transfers.unshift(transfer);addNotification({kind:'TRANSFER',priority:priority==='EMERGENCY'?'HIGH':'MEDIUM',title:ambulance?'Ambulance assigned':'Transfer waiting for ambulance',message:ambulance?`${patientName(patientId)} assigned to ${ambulance.callSign}; synthetic ETA ${ambulance.etaMinutes} min.`:`${patientName(patientId)} transfer request is waiting for a compatible ambulance.`,patientId,facilityId:destinationFacilityId,roles:['COORDINATOR','NURSE','MANAGER','PATIENT_NAVIGATOR'],actionView:'transfers'});logAudit(req.currentUser!.displayName,'transfer.request','Transfer',transfer.id,'UI');res.status(201).json({transfer:transferView(transfer),autoAssigned:Boolean(ambulance)})});
app.post('/api/transfers/:id/assign',auth,requireRole(...transferManageRoles),(req,res)=>{const id=paramValue(req.params.id),transfer=transfers.find(t=>t.id===id);if(!transfer||!visibleTransfersFor(req.currentUser!).some(t=>t.id===id))return res.status(404).json({error:'Transfer not found in authorised scope'});if(!['REQUESTED','ASSIGNED'].includes(transfer.status))return res.status(409).json({error:'Transfer cannot be assigned in its current state'});const requestedId=String(req.body?.ambulanceId||''),ambulance=requestedId?ambulances.find(a=>a.id===requestedId):findAmbulance(transfer.requiredLevel);if(!ambulance||!ambulanceCanServe(ambulance,transfer.requiredLevel))return res.status(409).json({error:'No compatible synthetic ambulance is currently available'});if(transfer.ambulanceId&&transfer.ambulanceId!==ambulance.id)releaseAmbulance(transfer.ambulanceId);assignAmbulance(transfer,ambulance);addNotification({kind:'TRANSFER',priority:transfer.priority==='EMERGENCY'?'HIGH':'MEDIUM',title:'Ambulance assigned',message:`${patientName(transfer.patientId)} assigned to ${ambulance.callSign}; synthetic ETA ${ambulance.etaMinutes} min.`,patientId:transfer.patientId,facilityId:transfer.destinationFacilityId,actionView:'transfers'});logAudit(req.currentUser!.displayName,'transfer.assign_ambulance','Transfer',transfer.id,'UI');res.json({transfer:transferView(transfer)})});
const transferTransitions:Record<TransferStatus,TransferStatus[]>={REQUESTED:['ASSIGNED','CANCELLED'],ASSIGNED:['EN_ROUTE','CANCELLED'],EN_ROUTE:['PATIENT_ON_BOARD','CANCELLED'],PATIENT_ON_BOARD:['ARRIVED'],ARRIVED:['COMPLETED'],COMPLETED:[],CANCELLED:[]};
app.post('/api/transfers/:id/status',auth,requireRole(...transferManageRoles),(req,res)=>{const id=paramValue(req.params.id),transfer=transfers.find(t=>t.id===id);if(!transfer||!visibleTransfersFor(req.currentUser!).some(t=>t.id===id))return res.status(404).json({error:'Transfer not found in authorised scope'});const status=String(req.body?.status||'') as TransferStatus;if(!transferTransitions[transfer.status]?.includes(status))return res.status(409).json({error:`Invalid transfer transition from ${transfer.status} to ${status}`});const from=transfer.status;transfer.status=status;transfer.updatedAt=nowIso();if(['COMPLETED','CANCELLED'].includes(status))releaseAmbulance(transfer.ambulanceId);addNotification({kind:'TRANSFER',priority:['CANCELLED'].includes(status)?'HIGH':'MEDIUM',title:'Patient transfer updated',message:`${patientName(transfer.patientId)} transfer changed from ${from.toLowerCase().replaceAll('_',' ')} to ${status.toLowerCase().replaceAll('_',' ')}.`,patientId:transfer.patientId,facilityId:transfer.destinationFacilityId,actionView:'transfers'});logAudit(req.currentUser!.displayName,`transfer.${status.toLowerCase()}`,'Transfer',transfer.id,'UI');res.json({transfer:transferView(transfer)})});
app.post('/api/ambulances/:id/status',auth,requireRole('ADMIN','COORDINATOR','MANAGER'),(req,res)=>{const id=paramValue(req.params.id),ambulance=ambulances.find(a=>a.id===id);if(!ambulance)return res.status(404).json({error:'Ambulance not found'});const status=String(req.body?.status||'') as AmbulanceStatus;if(!['AVAILABLE','MAINTENANCE'].includes(status))return res.status(400).json({error:'Manual fleet status may be AVAILABLE or MAINTENANCE only'});if(ambulance.status==='DISPATCHED'&&transfers.some(t=>t.ambulanceId===ambulance.id&&!['COMPLETED','CANCELLED'].includes(t.status)))return res.status(409).json({error:'Cannot manually change a dispatched ambulance with an active transfer'});ambulance.status=status;ambulance.updatedAt=nowIso();logAudit(req.currentUser!.displayName,'ambulance.status.update','Ambulance',ambulance.id,'UI');res.json({ambulance:ambulanceView(ambulance)})});

app.get('/api/outcomes',auth,(req,res)=>{if(req.currentUser!.role==='PATIENT')return res.status(403).json({error:'Outcome analytics are not available in the patient role'});const scoped=managementRoles.includes(req.currentUser!.role)?referrals:visibleReferralsFor(req.currentUser!);res.json({syntheticData:true,disclaimer:'Observed synthetic outcomes only. These values are not risk-adjusted, do not represent real hospitals and must not be interpreted as a clinical quality ranking.',methodology:'Shows referral volume and recorded synthetic outcomes. A production comparison would require validated outcome definitions, case-mix/risk adjustment, confidence intervals, minimum sample sizes and governance review.',facilities:outcomeSummary(scoped)})});
app.get('/api/caregaps',auth,(req,res)=>{if(req.currentUser!.role==='PATIENT')return res.status(403).json({error:'Operational care-gap queue is not available in the patient role'});const scopedReferrals=visibleReferralsFor(req.currentUser!),scopedPatients=patients.filter(p=>canReadPatient(req.currentUser!,p.id)),scopedTransfers=visibleTransfersFor(req.currentUser!),gaps:any[]=[];for(const r of scopedReferrals){if(['SUBMITTED','RECEIVED','INFO_REQUESTED'].includes(r.status)&&Date.now()-Date.parse(r.updatedAt)>24*3600000)gaps.push({id:`gap-ref-${r.id}`,type:'REFERRAL_DELAY',severity:'HIGH',patientId:r.patientId,patientName:patientName(r.patientId),detail:`Referral ${r.id} has been waiting more than 24 hours`,action:'Review referral ownership and next permitted action'});if(r.status==='MISSED'||r.status==='FOLLOWUP_REQUIRED')gaps.push({id:`gap-follow-${r.id}`,type:'FOLLOW_UP',severity:'MEDIUM',patientId:r.patientId,patientName:patientName(r.patientId),detail:`Referral ${r.id} requires follow-up`,action:'Confirm patient contact and rescheduling workflow'});if(r.requiresBed&&r.bedType&&availableBeds(r.destinationFacilityId,r.bedType)===0)gaps.push({id:`gap-bed-${r.id}`,type:'CAPACITY_CONSTRAINT',severity:'HIGH',patientId:r.patientId,patientName:patientName(r.patientId),detail:`No synthetic ${r.bedType.toLowerCase().replace('_',' ')} bed is currently available at ${facilityName(r.destinationFacilityId)}`,action:'Review destination capacity and authorised alternatives'})}for(const t of scopedTransfers){if(t.status==='REQUESTED'&&Date.now()-Date.parse(t.createdAt)>30*60000)gaps.push({id:`gap-transfer-${t.id}`,type:'TRANSFER_DELAY',severity:'HIGH',patientId:t.patientId,patientName:patientName(t.patientId),detail:`Transfer ${t.id} has no assigned ambulance after 30 minutes`,action:'Review ambulance availability or escalation route'})}for(const p of scopedPatients.slice(0,35)){if(!p.results.length)gaps.push({id:`gap-data-${p.id}`,type:'DATA_COMPLETENESS',severity:'LOW',patientId:p.id,patientName:`${p.firstName} ${p.surname}`,detail:'No diagnostic result is present in the current synthetic longitudinal record',action:'Verify whether a result exists in an authorised source system'})}for(const v of vaccinations.filter(v=>v.status==='OVERDUE'&&canReadPatient(req.currentUser!,v.patientId)).slice(0,10)){gaps.push({id:`gap-vax-${v.id}`,type:'VACCINE_OVERDUE',severity:'MEDIUM',patientId:v.patientId,patientName:patientName(v.patientId),detail:`${v.vaccine} ${v.dose} is overdue in the synthetic record`,action:'Confirm immunisation status and authorised follow-up'})}res.json({syntheticData:true,definition:'Operational, capacity, transfer, medication/vaccine and information-continuity gaps only; not clinical diagnoses.',gaps:gaps.slice(0,70)})});

app.get('/api/audit',auth,requireRole('AUDITOR','MANAGER','ADMIN'),(_req,res)=>res.json({auditEvents}));
app.get('/api/admin/users',auth,requireRole('ADMIN'),(_req,res)=>res.json({users:users.map(safeUser),roles:[...new Set(users.map(u=>u.role))]}));
app.get('/api/admin/openai-settings',auth,requireRole('ADMIN'),(_req,res)=>res.json(getOpenAISettings()));
app.put('/api/admin/openai-settings',auth,requireRole('ADMIN'),(req,res)=>{const settings=updateOpenAISettings({enabled:req.body?.enabled,model:req.body?.model,baseUrl:req.body?.baseUrl,apiKey:req.body?.apiKey,allowSyntheticDemoData:req.body?.allowSyntheticDemoData});logAudit(req.currentUser!.displayName,'admin.openai_settings.update','AISettings','openai','UI');res.json(settings)});
app.post('/api/admin/openai-settings/test',auth,requireRole('ADMIN'),async(req,res)=>{try{const result=await testOpenAISettings();logAudit(req.currentUser!.displayName,'admin.openai_settings.test','AISettings','openai','UI',result.ok?'SUCCESS':'DENIED',result.message);res.status(result.ok?200:400).json(result)}catch(error:any){res.status(502).json({ok:false,message:error?.message||'OpenAI connection test failed'})}});

app.post('/api/ayanda',auth,async(req,res)=>{const input=String(req.body?.input||'').slice(0,1000);if(!input.trim())return res.status(400).json({error:'Input is required'});const response=await answerAyanda(input,{patients:patients.filter(p=>canReadPatient(req.currentUser!,p.id)),referrals:visibleReferralsFor(req.currentUser!),facilities,ambulances});logAudit(req.currentUser!.displayName,'ai.query','AIInteraction',randomUUID(),req.body?.source==='VOICE'?'VOICE':'AI');res.json(response)});
app.post('/api/ayanda/execute',auth,requireRole('CLINICIAN','ADMIN'),(req,res)=>{if(req.body?.confirmed!==true)return res.status(400).json({error:'Explicit confirmation is required'});const action=req.body?.action;if(action?.tool!=='create_referral_draft'||!action.patientId||!canReadPatient(req.currentUser!,action.patientId))return res.status(400).json({error:'Unsupported, invalid or unauthorised action'});const destination=facilities.find(f=>f.id===action.destinationFacilityId);if(!destination)return res.status(400).json({error:'Invalid destination'});const bedType=bedTypeForService(String(action.service||''));if(bedType&&availableBeds(destination.id,bedType)<1)return res.status(409).json({error:`No synthetic ${bedType.toLowerCase().replace('_',' ')} bed is available at ${destination.name}`,alternatives:alternativesFor(String(action.service||''),bedType)});const referral:Referral={id:`ref-${Date.now()}`,patientId:action.patientId,service:String(action.service||'Specialist review').slice(0,120),reason:`AI-assisted draft for ${String(action.service||'specialist').toLowerCase()} review; clinician must verify clinical rationale`,sourceFacilityId:req.currentUser!.facilityId||'fac-clinic-1',destinationFacilityId:destination.id,owner:req.currentUser!.displayName,status:'DRAFT',priority:'ROUTINE',createdAt:nowIso(),updatedAt:nowIso(),requiresBed:Boolean(bedType),bedType,events:[{id:randomUUID(),at:nowIso(),actor:req.currentUser!.displayName,to:'DRAFT',note:'Draft created after explicit human confirmation and capacity check',source:'AI'}]};referrals.unshift(referral);logAudit(req.currentUser!.displayName,'ai.tool.create_referral_draft','Referral',referral.id,'AI');res.status(201).json({referral:referralView(referral),text:'Referral draft created after the synthetic destination-capacity check. It remains a draft until an authorised clinician reviews and submits it.'})});

